(window.MUSEUM_PAINT_T = window.MUSEUM_PAINT_T || {})["tr"] = {"ui":{"lead":"İnsanlar oyunları yalnızca oynamadı, resmini de yaptı. 3300 yıllık resim ve heykeli büyütüp ayrıntılarına bakın.","details":"Ayrıntılar","links":"Oyuna bak ya da oyna","record":"Eser hakkında","game":"Oyun","exhibit":"Koleksiyon","room":"Salon","room_chance":"Şans","hint":"Büyütmek için kıstırın ya da tekerleği kullanın · taşımak için sürükleyin · bir numaraya dokunun","r_artist":"Sanatçı","r_date":"Tarih","r_place":"Yer","r_medium":"Teknik","r_size":"Boyut","r_museum":"Müze","r_credit":"Edinim","r_rights":"Görsel","met":"Metropolitan Sanat Müzesi","cc0":"Açık erişim (kamu malı)","metlink":"Eserin müzedeki sayfası","credit":"Görseller: Metropolitan Sanat Müzesi, Cleveland Sanat Müzesi, Chicago Sanat Enstitüsü ve Rijksmuseum, açık erişim (kamu malı).","cma":"Cleveland Sanat Müzesi","aic":"Chicago Sanat Enstitüsü","rijks":"Rijksmuseum, Amsterdam"},"nefertari":{"title":"Senet oynayan Kraliçe Nefertari","artist":"Nina de Garis Davies (kopya)","date":"aslı MÖ y. 1290–1224 · kopya 1921–22","place":"Mısır (Kraliçeler Vadisi)","game":"Senet","medium":"Kâğıt üzerine tempera (yarı boyutta kopya)","p":["Nefertari, II. Ramses’in baş eşiydi. Bu, Kraliçeler Vadisi’ndeki mezarındaki bir resmin, 1921–22’de mezarın içinde yapılmış kopyasıdır; duvardaki çatlaklar ve kayıplar bile kopyalanmıştır.","Kraliçe bir tahtanın önünde oturmuş, görünmeyen bir rakiple senet oynuyor. Bir mezara resmedilen oyunun, eğlenceden öte bir anlamı olduğu düşünülür: öbür dünyaya giden yolculuğu kazanmak."],"spots":[["İki tür taş","Tahtada sivri başlı taşlar ve makara biçimli taşlar duruyor: her oyuncuya bir takım."],["Kraliçenin eli","Parmakları bir taşa uzanıyor."],["Tahta ve sehpa","Tahta yandan gösterildiği için haneler görünmüyor. İnce ayaklı bir sehpanın üstünde duruyor."],["Adı","Kraliçenin adı oval bir çerçevenin, kartuşun içine yazılmış."],["Görünmeyen rakip","Karşısında kimse yok: Kraliçe görünmeyen bir rakiple oynuyor."]]},"hydria":{"title":"Tahta oyunu oynayan Akhilleus ve Aias (su testisi)","artist":"Leagros Grubu’na atfedilir","date":"MÖ y. 510","place":"Yunanistan (Attika)","game":"Bir zar oyunu","medium":"Pişmiş toprak (siyah figür)","p":["Truva kuşatması sırasında iki Yunan kahramanı, Akhilleus ve Aias, bir tahtanın başında vakit geçiriyor. Sahneyi MÖ 540 dolaylarında çömlekçi ve ressam Eksekias tasarlamıştır; aslı Vatikan Müzeleri’ndeki bir amforada durur.","Konu yaklaşık MÖ 540–480 arasında çok sevilmiş, 150’den fazla örneği bilinir. Bu testide ortada tanrıça Athena duruyor. Kahramanlar, taşların zar atışına göre ilerlediği bir oyun oynuyor."],"spots":[["Athena","Tanrıça Athena ikisinin arasında duruyor."],["Soldaki kahraman","Mızrağı hâlâ elinde, tahtaya eğiliyor."],["Sağdaki kahraman","O da silahlarını bırakmamış: savaşın ortasında kısa bir oyun."],["Tahta","Aralarındaki alçak blok tahtadır."],["Omuz","Testinin omzunda bir savaş arabası yola çıkıyor."]]},"liubo":{"title":"Liubo oynayan iki oturan figür","date":"MÖ 1. yüzyıl – MS 1. yüzyıl","place":"Çin (Han hanedanı)","game":"Liubo","medium":"Boyalı pişmiş toprak","p":["Han Çini’nin gözde oyunu liuboyu oynayan iki kişi. Bu tür figürler, hayatın zevklerinin ölümden sonra da sürmesi dileğiyle mezarlara konurdu.","Fotoğrafta aralarında bu müzenin koleksiyonundaki liubo tahtası ve kemik taşları duruyor. Figürler, kızışmış bir oyunun dramatik bir anını yakalıyor."],"spots":[["Liubo tahtası","Koleksiyondaki “Liubo Tahtası ve Taşları” ile aynı tahta: T, L ve V işaretlerine bakın."],["Soldaki oyuncu","Tahtayı sakin sakin inceliyor."],["Sağdaki oyuncu","Eli havada, ağzı kocaman açık: kazandıran hamleyi mi yaptı?"],["Tahtadaki taşlar","Kemik taşlar tahtanın iki ucunda duruyor."],["Tahta dışındaki taşlar","Yerde de taşlar var."]]},"shahnama":{"title":"“Büzürcmihr Hint oyunu satrancı çözer”, Şah Tahmasb’ın Şehnamesi’nden","artist":"Resim Abdülvahhab’a atfedilir","date":"y. 1530–35","place":"İran (Tebriz)","game":"Satranç","medium":"Kâğıt üzerine opak suluboya, mürekkep, gümüş ve altın","p":["Firdevsi’nin destanı Şehname’den (Şahlar Kitabı) bir sahne. Hint kralı bir elçiyle satranç tahtası ve taşları gönderip İran kralı Nuşirevan’a meydan okur: oyunun nasıl oynandığını bulursa Hindistan haraç ödeyecektir.","Bunu vaktinde ancak genç bilge Büzürcmihr çözer. Şehname’de İran karşılık olarak tavlayı gönderir ve Hintliler onu çözemez. Kral ve saray halkı gözlerini tahtaya ve oyunculara dikmiş."],"spots":[["Satranç tahtası","Taşlar kareli bir tahtada duruyor; o kadar küçükler ki biçimleri zor seçiliyor."],["Kral Nuşirevan","Tahtında, bilmecenin çözülmesini bekliyor."],["Tahtanın çevresinde","Oyuncular tahtaya eğilmiş."],["Beyitler","Üstteki ve alttaki çerçevelerde Firdevsi’nin beyitleri yazılı."],["Saray halkı","Kırmızı uzun çubuklu sarıklı adamlar ayakta izliyor."]]},"chaupar":{"title":"Çaupar oynayan Şiva ve Parvati, bir Rasamancari serisinden","artist":"Nurpurlu Devidasa","date":"1694–95","place":"Hindistan (Basohli, Cammu)","game":"Çaupar (Ludo’nun atasının akrabası)","medium":"Kâğıt üzerine opak suluboya, mürekkep, gümüş ve altın","p":["15. yüzyıldan bir Sanskrit aşk şiiri olan Rasamancari’yi resimleyen bir seriden bir sayfa. Tanrı Şiva ile eşi Parvati, bir kaplan postunun üstünde haç biçimli bir tahtanın başında oturuyor.","Şiva hile yaparak Parvati’nin kolyesini almış, Parvati de geri vermesi için yalvarıyor. Cesur renkler, belirsiz bir mekân derinliği, anlam taşıyan renk ve jestler: Basohli okulunun izleri."],"spots":[["Haç biçimli tahta","Çaupar ve pachisi bu haç biçimli tahtada oynanır."],["Tahtadaki beyaz çubuklar","Muhtemelen çauparın uzun zarları (pasa)."],["Şiva","Bembeyaz gövde, boynunda bir yılan."],["Parvati","Elini uzatmış, kolyesini geri istiyor."],["Kaplan postu","İkisi de bir kaplan postunun üstünde oturuyor."]]},"shogi":{"title":"Şogi oynayan genç bir kadın ve erkek (“Çūnagon Kanesuke”, Otuz Altı Ölümsüz Şair serisinden)","artist":"Suzuki Harunobu","date":"y. 1767–69","place":"Japonya (Edo)","game":"Şogi","medium":"Renkli ağaç baskı (nişiki-e)","p":["Otuz Altı Ölümsüz Şair’e gönderme yapan bir seriden bir baskı; bu, şair Çūnagon Kanesuke’yi temsil ediyor. Bir yaz gecesi, bir cibinliğin yanında genç bir kadınla bir erkek şogi tahtasının başında.","Harunobu, birçok kalıpla basılan çok renkli baskıları yaygınlaştıran sanatçıdır. Tahtadaki taşlar bile ayrıntılı çizilmiş."],"spots":[["Ayaklı şogi tahtası","Bugünkü gibi ayaklı, kalın bir tahta."],["Küçük bir kutu","Muhtemelen taşların kutusu."],["Cibinlik","Yeşil bir cibinlik asılı: bir yaz gecesi."],["Fener","Ayaklı bir lamba tahtayı aydınlatıyor."],["Şiir","Bulut biçimli çerçevede şairin adı ve bir şiir var."]]},"sugoroku":{"title":"Sugoroku oynayan iki genç kadın","artist":"I. Utagawa Toyokuni","date":"Edo dönemi (18. yy. sonu – 19. yy. başı)","place":"Japonya (Edo)","game":"Ban-sugoroku (tavlanın akrabası)","medium":"İki parçalı renkli ağaç baskı","p":["İki baskı birleşerek geniş bir resim oluşturuyor: bir odada toplanmış genç kadınlar ban-sugoroku oynuyor. Oyun tavlanın akrabasıdır; bu koleksiyondaki Şōsōin sugoroku tahtasıyla aynı soydandır.","Tahtada beyaz ve siyah pullar var; sağdaki genç kadın zarları sallamak için bir kap tutuyor. Pencereden Fuji Dağı görünüyor."],"spots":[["Tahta","Uzun hanelerinde beyaz ve siyah pullar."],["Zar kabı","Zarlar bu kapta sallanır."],["Tahta dışındaki pullar","Çoktan toplanmış mı, yoksa henüz girmemiş mi?"],["Fuji Dağı","Pencerenin ardında Fuji."],["Birleşme yeri","İki baskı burada birleşiyor."]]},"eakins":{"title":"Satranç Oyuncuları","artist":"Thomas Eakins","date":"1876","place":"ABD (Philadelphia)","game":"Satranç","medium":"Ahşap üzerine yağlıboya","p":["Philadelphia’daki bir evin salonunda iki arkadaş satranç oynuyor, sanatçının babası Benjamin Eakins de izliyor. Eakins özenli mekân kurgusunu ve titiz ayrıntıyı Paris’teki hocası Gérôme’dan öğrenmişti.","1881’de Satranç Oyuncuları, Metropolitan Müzesi’nin yaşayan bir sanatçıdan bağış olarak kabul ettiği ilk eser oldu."],"spots":[["Satranç taşları","Loş odada tahtadaki taşlar ışıkta öne çıkıyor."],["Sanatçının babası","Ayakta oyunu izleyen kişi: Benjamin Eakins."],["Sağdaki oyuncu","Ressam George W. Holmes, sanatçının babasının arkadaşı."],["Çekmece","Latince bir yazı: “Bunu Benjamin Eakins’in oğlu ’76’da yaptı.”"],["Şöminenin üstü","Eakins’in hocası Gérôme’un bir tablosunun reprodüksiyonu."],["Kedi","Yerde, oyunla ilgilenmeyen tek kişi kedi gibi."]]},"weiqi":{"title":"Weiqi oynayan ölümsüzler tabağı","artist":"Bilinmiyor","date":"1425–36 (Ming hanedanı, Xuande dönemi)","place":"Çin","game":"Go (weiqi)","medium":"Oyma kırmızı ve yeşil lake","size":"Y. 3,5; G. 14,9; U. 23,5 cm","credit":"Florence ve Herbert Irving bağışı, 2015","p":["Oyma lakeden bir tabak: onlarca kat lake sürülüp sonra oyulmuştur; kırmızının altında yeşil bir kat vardır, oyma derinliği renkleri ortaya çıkarır. Dilimli kenarın içinde ölümsüzler bir çamın altında go oynar.","Çin’de “çürümüş balta sapı” anlamına gelen Lanke efsanesi vardır: oduncu Wang Zhi dağda ölümsüzlerin go oyununu seyreder, kendine geldiğinde o kadar zaman geçmiştir ki baltasının sapı çürümüştür. Tahta başındaki ölümsüzler sevilen bir konuydu. Ayaktaki kişinin kim olduğunu kayıtlar söylemez."],"spots":[["Tahta","İki ölümsüzün arasındaki go tahtası, çizgilerine kadar oyulmuş."],["Oynayan ölümsüzler","Kayaların yanında tahtanın başında oturan iki kişi."],["Ayaktaki kişi","Biraz uzakta duran bir kişi. Efsanedeki oduncuyu hatırlatır ama kim olduğu bilinmez."],["Ay","Gökte yuvarlak bir ay (belki de güneş)."],["Çam","Dallarını geniş açmış bir çam; uzun ömrü ve ölümsüzler diyarını simgeleyen bir ağaç."],["Şakayıklı kenar","Kenara iri şakayıklar ve yapraklar oyulmuştur."]]},"webb":{"title":"Tavla oynayanlar (dolap)","artist":"Philip Webb (tasarım), Edward Burne-Jones (resim), Morris, Marshall, Faulkner & Co. (yapım)","date":"1861","place":"Britanya (Londra)","game":"Tavla","medium":"Boyalı çam, deri üzerine yağlıboya, pirinç, bakır","size":"Y. 185,4; G. 114,3; D. 53,3 cm","credit":"Rogers Fonu, 1926","p":["William Morris’in 1861’de arkadaşlarıyla kurduğu firmanın en erken mobilyalarından biri. Kapakların derisi üzerine, Orta Çağ giysileri içinde tavla oynayan bir erkek ve bir kadın yağlıboyayla resmedilmiştir. 1862 Londra Uluslararası Sergisi’nde gösterildi.","Güzel sanatlarla uygulamalı sanatlar arasındaki sınırı kaldırmak isteyen Arts and Crafts hareketinin amacını özetler. Deri zemin, Orta Çağ tekniğiyle minik noktalarla zımbalanmıştır."],"spots":[["Tahta","İkisinin arasındaki masada duran tavla tahtası."],["Erkek","Elinde bir pul, tahtaya bakan genç bir adam."],["Kadın","Karşısında elinde pul (ya da zar kabı) tutan bir kadın."],["Ayaklarının dibindeki çiçekler","Oyuncuların ayaklarının dibinde çiçekler açar."],["Zımbalanmış deri","Deri zemin, ışığı yakalayan ince noktalarla zımbalanmıştır."],["Baklava bantları","Altın zemin üzerine baklava desenli bantlar kapakları üstten ve alttan çerçeveler."]]},"liberale":{"title":"Satranç Oynayanlar","artist":"Liberale da Verona","date":"1475 dolayları","place":"İtalya (Verona)","game":"Satranç","medium":"Ahşap üzerine tempera","size":"34,9 × 41,3 cm","credit":"Maitland F. Griggs Koleksiyonu, Maitland F. Griggs vasiyeti, 1943","p":["Rönesans İtalya’sında gelinin çeyizini koyduğu süslü sandık “cassone”nin ön yüzünden bir parça. Liberale, Siena Katedrali’nin koro kitaplarındaki minyatürleriyle de tanınır.","Adı bilinmeyen bir aşk öyküsünden bir an görülür. Eş parçada pencerenin önündeki genç kız bir delikanlıyı içeri çağırıyor gibidir; burada ise ikisi satranç oynar. Müzeye göre kız kaybetmek üzeredir. Satranç, dönemin aşk edebiyatında kur yapmanın sevilen bir simgesiydi."],"spots":[["Satranç tahtası","Koyu taşların dizildiği kırmızı-beyaz tahta; oyun sona yaklaşmış görünüyor."],["Delikanlı","Tahtaya uzanan delikanlı; oyunu o kazanacak gibi."],["Genç kız","Karşısında oturuyor; eş parçada onu pencereden çağırır."],["Pencere","Açık pencerenin ardında bir tepe ve gökyüzü."],["İzleyen gençler","Kollarını kavuşturmuş adamlar oyunu izliyor."],["İzleyen genç kızlar","Sütunun ardından oyuna bakan kızlar."]]},"mirror":{"title":"Satranç oynayan çiftli ayna kabı","artist":"Bilinmiyor","date":"1325–50","place":"Fransa (Paris)","game":"Satranç","medium":"Fildişi","size":"Çap 10,2 cm","credit":"J. H. Wade Fonu ile satın alındı, 1940","p":["Avuç içi büyüklüğündeki bu fildişi disk bir el aynasının kapağıydı. 14. yüzyıl Paris’inde cilalı metal ayna iki fildişi levha arasına konup yanda taşınırdı; böyle oymalar sarayın ve soyluların sevdiği lüks eşyalardı.","Perdeleri toplanmış bir çadırda bir delikanlı ile bir hanım satranç oynuyor. Orta Çağ öykülerinde satranç hem aşkı hem savaşı simgelerdi. Çiftin Tristan ile İsolde ya da Lancelot ile Guinevere olduğu öne sürülmüştür, ama kimse bilmiyor. Müze ziyaretçilerine soruyor: Sizce kim kazanıyor?"],"spots":[["Satranç tahtası","Tek ayaklı bir masa üzerindeki tahta; üstünde birkaç taş var."],["Delikanlı","Sıradaki hamlesini yapmak için uzanıyor."],["Hanım","Başörtülü bir kadın; parmak uçları bir taşa dokunuyor."],["Kapalı el","Öbür eli yumruk hâlinde kucağında. Aldığı bir taşı mı tutuyor?"],["Çadır","İki yana bağlanmış perdeler; ayna kaplarındaki satranç sahnelerinin sevilen dekoru."]]},"morris":{"title":"Bir oyun tahtası (dokuz taş)","artist":"Peter Flötner","date":"1500–46","place":"Almanya","game":"Dokuz taş (Nine Men’s Morris)","medium":"Ağaç baskı","credit":"Charles W. Harkness Vakıf Fonu, 1923","p":["Rönesans Nürnberg’inin en yetenekli heykeltıraşlarından Peter Flötner’in bir ağaç baskısı. Flötner süsleme desenleri, mobilya, kuyumcu modelleri ve hicviyle ünlü bir oyun kâğıdı destesi de tasarladı. Kıvrılan yaprakların altında, Almancada “Mühle” denen dokuz taş oyununun tahtası saklı: kenar ortalarından birbirine bağlanan iç içe üç kare.","Tahtada 24 nokta var. Kendi üç taşını bir sıraya dizen (değirmen) rakibin bir taşını alır. Bu tür baskılar zanaatkârlara da örnek olurdu; müze bu yaprağı kuyumcu modelleri ve tasarımları sergisinde gösterdi. Kâğıdın üstünde mi oynandığı, yoksa ağaca ya da metale mi aktarıldığı bilinmiyor."],"spots":[["Orta kare","En içteki kare; ince örgü desenle dolu."],["Dış köşe","Dış karenin köşesi — taşların konduğu 24 noktadan biri."],["Orta köşe","Ortadaki karenin köşeleri de birer noktadır."],["Bağlantı çizgileri","Üç kareyi kenar ortalarından bağlayan şeritler; taşlar bunların üstünde de yürür."],["Maske","Üstte, altta ve yanlarda kıvrımlı kartuşlar ve yüzler — Rönesans grotesk süslemesi."],["Asma bordürü","Siyah zemin üzerine beyaz oyulmuş yapraklar ve meyveler."]]},"leifeng":{"title":"Leifeng Pagodası oyun tahtası","artist":"Bilinmiyor","date":"1736–95 (Qianlong dönemi)","place":"Çin","game":"Yarış oyunu","medium":"Ağaç baskı; kâğıt üzerine mürekkep","size":"31 × 29,8 cm","credit":"J. H. Wade Fonu ile satın alındı, 2025","p":["Qing Çini’nde İmparator Qianlong döneminden, oynamak için basılmış tek bir yaprak. Kareleri Beyaz Yılan Efsanesi’nin kahramanlarıyla dolu: yılan ruhu Bai Suzhen (“Beyaz Hanım”), arkadaşı Xiaoqing (“Küçük Yeşil”), genç Xu Xuan (sonraki anlatımlarda Xu Xian) ve sonunda Beyaz Hanım’ı Batı Gölü kıyısındaki Leifeng Pagodası’nın altına hapseden keşiş Fahai.","Yol, 起馬 (“yola çık”) yazılı kareden sarmal çizerek ortadaki pagodaya gider. Oyuncular herhalde Batı’daki Kaz Oyunu gibi zarla öykü boyunca yarışırdı; kuralları kayıtlı değil. Müzeye göre bu tür renkli baskılar şehirlerde satılır, duvarlara asılır, kent görsel kültürünün parçası olurdu — her renk ayrı oyulmuş bir kalıpla basılırdı."],"spots":[["Başlangıç","起馬, “yola çık” yazılı kare — büyük olasılıkla başlangıç noktası."],["Beyaz Hanım ile Küçük Yeşil","Yılan ruhu Bai Suzhen ve arkadaşı Xiaoqing."],["Xu Xuan","Beyaz Hanım’la evlenen delikanlı."],["Keşiş Fahai","Onu pagodanın altına hapseden keşiş."],["Leifeng Pagodası","Hangzhou’da Batı Gölü kıyısındaki pagoda; öykünün bittiği yer."],["Merkez","Pagodanın önünde oturan bir kadın ve diz çökmüş bir adam — öykünün son sahnesi, belki de bitiş."]]},"tutinama":{"title":"Yaralı maymun satranç arkadaşı prensin elini ısırıyor (Tuti-nâme, “Papağanın Masalları”ndan)","artist":"Dasavanta","date":"1560 dolayları","place":"Hindistan (Ekber’in Babür sarayı)","game":"Satranç","medium":"Kâğıt üzerine guaj, mürekkep ve altın","size":"20 × 14,2 cm (resim 10,2 × 10,6 cm)","credit":"Bayan A. Dean Perry bağışı, 1962","p":["Babür imparatoru Ekber’in sarayında hazırlanan Tuti-nâme’den (“Papağanın Masalları”) bir resim. Anne papağanın, yavrularını tilki yavruları gibi başka türden hayvanlarla dostluk kurmaktan sakındırmak için anlattığı öykülerden biri: satrançta usta bir maymun sık sık bir prensle satranç oynarmış.","Bir gün konukların önünde maymun kaba bir şaka yapmış, prens onu tokatlamış, maymun da prensin elini ısırmış. Sağda, dışarıda hizmetkârlar yemek hazırlarken konuklar şaşkınlıkla bakıyor. Alttaki yazı, sonradan Babür sarayının en ünlü ustalarından biri olacak Dasavanta’nın adını veriyor; genç ressam resminin altına serin bir mavi katman sürmüş."],"spots":[["Maymun","Satranç arkadaşı prensin elini ısırıyor."],["Prens","Eli ısırılan prens."],["Satranç tahtası","Yerde kırmızı kareli bir tahta."],["Şaşkın konuklar","Toplantıya çağrılan konuklar."],["Yemek hazırlığı","Dışarıda kazanları ateşe koyan hizmetkârlar."],["Farsça metin","Yukarıda öykü Farsça yazılmış."]]},"teniers":{"title":"Tavla oyunu","artist":"David Teniers","date":"1640’lar","place":"Flandre","game":"Tavla (backgammon)","medium":"Ahşap üzerine yağlıboya, tuvale aktarılmış","size":"59 × 80,6 cm","credit":"Bay ve Bayan Samuel D. Wise bağışı, 1943","p":["Flaman ressam Teniers’in yüksek bahisli bir tavla maçını gösteren tablosu. Oyun çok eskidir: bugünkü biçimi 1400’lerde ortaya çıktı, “backgammon” adı da aşağı yukarı bu resmin yapıldığı sıralarda doğdu. 1600’lerde çok yaygındı ve sık sık para için oynanırdı.","İki oyuncunun çevresini seyirciler sarmış, duvar dibinde de biri puan tutuyor. Seyreden kadınlardan — biri pencereden sarkıyor — yola çıkan müze, odanın bir genelevin oyun odası olduğunu düşünüyor. Böyle oyun sahneleri çoğu zaman bir ders taşırdı: kumar aptalca, hatta kötüdür ve vakit kaybıdır."],"spots":[["Tahta","Masada açık bir tavla tahtası; oyun sürüyor."],["Beyazlı adam","Sırtı dönük oyuncu, pullarına uzanıyor."],["Düşünceli adam","Rakibi, elini yanağına dayamış."],["Puan tutan","Duvardaki tahtaya işaret koyan adam — puan mı, bahis mi?"],["Penceredeki kadın","Yukarıdan bakan yaşlı bir kadın."],["Arka oda","Arkada erkekler genç bir kadının yanında içiyor."]]},"imari":{"title":"Go oynayan iki adamlı tabak","artist":"Bilinmiyor","date":"18. yüzyıl","place":"Japonya (Edo dönemi)","game":"Go","medium":"Kalıpta biçimlendirilmiş porselen, sır üstü boya (Hizen, Imari üslubu)","size":"2,4 × 13,8 cm","credit":"Severance ve Greta Millikin Koleksiyonu, 1964","p":["Bu küçük kare tabakta iki adam bir çam ağacının altında go oynuyor: sarılı olan, doğrudan yere konmuş tahtanın karşısında oturuyor; yeşilli rakibi ağaca yaslanmış.","Hizen’de (bugünkü Saga ve Nagasaki) yapılmış bir Imari porseleni; yeşilleri Kutani emayelerini andırıyor. Japonya’nın Avrupa’ya porselen tedarikinde Çin’in yerini aldığı dönemde ihracat için yapıldı."],"spots":[["Go tahtası","Yere doğrudan konmuş, çizgili bir tahta."],["Sarılı adam","Tahtanın karşısında oturuyor."],["Yeşilli adam","Rakibi; gülümseyerek ağaca yaslanmış."],["Çam","Başlarının üstüne dallarını uzatan çam."],["Kırmızı çerçeve","Köşeleri kesik kırmızı bir çerçeve sahneyi kuşatıyor."]]},"shoei":{"title":"Dört Hüner (bir çift paravandan biri)","artist":"Kanō Shōei’ye atfedilir","date":"16. yüzyıl sonu–17. yüzyıl başı","place":"Japonya (Momoyama dönemi)","game":"Go","medium":"Bir çift altı kanatlı paravandan biri; kâğıt üzerine mürekkep ve hafif renk","size":"153 × 358,6 cm","credit":"John L. Severance Fonu, 1979","p":["Kanō okulundan Kanō Shōei’ye atfedilen altı kanatlı bir paravan. Eşiyle birlikte kültürlü bir Çinli beyefendiden beklenen “dört hüner”i gösterir: qin çalmak, qi (go) oynamak, hat ve resim. Burada yüksek mevkili Çinli beyefendiler hizmetkârlarıyla çamların altında kırda dinleniyor.","Ortada iki adam go oynuyor, üçüncüsü izliyor. Yanlarındaki masada kitaplar ve hâlâ kumaş kılıfında duran, çalınmayı bekleyen bir qin var. Sahne eğlenceyle resmiyeti dengeliyor. Müze, hizmetkârlardan birinin sudaki bir balığın hareketine dalıp gittiğine dikkat çekiyor."],"spots":[["Go tahtası","Ayaklı bir tahta; iki beyefendi karşılıklı oynuyor."],["Beyefendiler","İki oyuncu ve izleyen üçüncüsü."],["Masa","Büyük olasılıkla kitapların ve kılıfındaki qin’in durduğu masa."],["Hizmetkârlar","Masanın yanında bekleyen hizmetkârlar."],["Dalgın hizmetkâr","Su kıyısına uzanmış, bir balığı izliyor."],["Çam","Sahnenin üstüne dallarını yayan büyük bir çam."]]},"umaya":{"title":"Ahır Paravanı (verandada go ve shogi)","artist":"Bilinmiyor","date":"16. yüzyılın başı","place":"Japonya (Muromachi dönemi)","game":"Go ve shogi","medium":"Altı kanatlı bir çift paravandan biri; kâğıt üzerine mürekkep, renk ve altın","size":"146,1 × 346,6 cm","credit":"Edward L. Whittemore Fund, 1934","p":["Altı kanadın birleştirildiği bu paravan bir çiftin tekidir. Asıl konu bölmelerdeki değerli atlar olabilir, ama öndeki verandada da pek çok şey oluyor.","Orada insanlar iki ayrı oyunda yarışıyor: solda go, sağda shogi. Müzeye göre sahnenin canlılığı, huzursuz atlarla oyunların sessiz stratejisi arasındaki karşıtlıktan doğuyor. Japonyada maymunların atları koruduğuna inanılır, ahırlarda bazen maymun beslenirdi."],"spots":[["Go tahtası","İnce çizgili, üzerinde siyah taşlar olan bir tahta."],["Siyah başlıklı iki adam","Uzun siyah eboshi başlıklı adamlar: yeşilli olan tahtaya uzanıyor, kırmızılı olan izliyor."],["Shogi tahtası","Büyük kareli bir tahta; go tahtasındakinden çok daha az kare var."],["Gülen rakip","Başı tıraşlı bir keşiş bir taş alırken karşısındaki adam elini başına koyup kahkaha atıyor. Biri az önce puan mı aldı?"],["Bir maymun","Verandanın ucunda, kırmızı giysili bir maymun mu?"],["Bir at","İplerle bağlı siyah bir at şaha kalkıyor."]]},"goryeo":{"title":"Go oynayan figürlerle kakmalı seladon testi","artist":"Bilinmiyor","date":"13. yüzyıl","place":"Kore (Goryeo hanedanı)","game":"Go (baduk)","medium":"Beyaz ve siyah astar kakmalı seladon","size":"Yük. 20,4 cm, çap 14,3 cm","credit":"John L. Severance bağışı, 1917","p":["Emzikli ve kulplu bir Goryeo seladon testisi. Kakma tekniği — kile çizgiler kazıyıp beyaz ve siyah astarla doldurmak, sonra sırlayıp pişirmek — Goryeo çömlekçilerinin ustalığıydı; burada yuvarlak bir çerçevenin içinde, söğüt altında oturan iki figür beyaz olarak belirir.","Aralarında bir tahta var; müze sahneyi go (Korecede baduk) oynayanların resimlerine benzetir. Çalgı çalmak, go, hat ve resim, kültürlü bilginin “dört hüneri” sayılırdı ve zarif buluşmaları zanaatkârlar için de bir motif oldu. İnsan figürlü Kore seladonu nadirdir."],"spots":[["Tahta","İkisinin arasındaki tahta, beyaz bir kare."],["Soldaki figür","Tahtaya dönük oturuyor."],["Sağdaki figür","Karşısında oturan rakip."],["Söğüt","Başlarının üstüne sarkan, siyah astarla çizilmiş söğüt dalları."],["Bulut çerçeve","Yuvarlak çerçevenin çevresini bulut gibi kıvrımlar dolanır."],["Çatlaklar","Sırdaki ince çatlaklar. Kil ile sır farklı oranda büzüldüğü için soğurken oluşur."]]},"kangra":{"title":"Terasta chaupar oynayan çift","artist":"Bilinmiyor","date":"y. 1790–1800","place":"Hindistan (Pahari, Kangra okulu)","game":"Chaupar","medium":"Kırmızı aşı boyasıyla ön çizimli desen","size":"19,4 × 13,2 cm","credit":"Edward L. Whittemore Fund, 1936","p":["Himalayaların eteğindeki Pahari tepelerinde, Kangralı bir sanatçının deseni. İlk taslak kırmızıyla (kırmızı aşı boyası) yapılmış, sonra siyahla netleştirilmiş. Üstünde renk olmadığından figürlerin ve eşyaların her çizgisi izlenebilir.","Bir terasta, haç biçimli bir tahtanın iki yanında oturan bir kadın ve bir erkek chaupar oynuyor; pachisi ile aynı haç üzerinde oynanan ve uzun zarlar (pasa) atılarak ilerlenen eski bir Hint yarış oyunu. Tahtaya kareler henüz çizilmemiş. Hizmetçiler çifte hizmet ediyor."],"spots":[["Haç biçimli tahta","Yerde haç biçimli bir tahta. Kareleri henüz çizilmemiş."],["Kadın","Avucu yukarıda — zarları atmak üzere mi?"],["Erkek","Sorguçlu sarıklı; elini tahtaya uzatıyor."],["Soldaki hizmetçi","Küçük bir şişe tutuyor ve bir bez uzatıyor."],["Sağdaki hizmetçi","Uzun saplı bir alet ve küçük bir kap tutuyor."],["Kırmızı taslak","Sarığın çevresinde, siyah çizgilerin altından kırmızı taslak görünüyor."]]},"vuillard":{"title":"Dama Oyunu (Manzaralar ve İç Mekânlar’dan)","artist":"Édouard Vuillard","date":"1899","place":"Fransa","game":"Dama","medium":"Renkli litografi (III/III. durum); baskı Auguste Clot, yayımcı Ambroise Vollard","size":"Görüntü 33 × 25,7 cm (kâğıt 38 × 30,8 cm)","credit":"Hanna Fund bağışı, 1951","p":["İzlenimci resim satıcısı Ambroise Vollard aynı zamanda önemli bir baskı yayımcısıydı. 1895’te Pierre Bonnard’a 12 renkli litografiden oluşan bir albüm ısmarladı; ardından pek çok albüm daha yayımladı. Vuillard’ın Manzaralar ve İç Mekânlar’ı da bunlardan biridir ve usta baskıcı Auguste Clot tarafından basılmıştır.","Bonnard ve Vuillard, İbranicede “peygamberler” anlamına gelen Nabiler grubundandı. Biçim ve rengin kendisiyle duygu anlatan yeni bir sanat arıyor, kent ve aile yaşamından sahneleri seviyorlardı. Desenlerle dolu bir odada iki adam dama tahtasının başında karşılıklı oturuyor, ayaktaki bir kadın oyunu izliyor. Fransızcada dama “dames” diye anılır; sol alttaki kurşun kalem notu “partie de dames”, yani “bir dama oyunu” diye okunur."],"spots":[["Tahta","Taşları dizilmiş küçük, kareli bir tahta."],["Soldaki adam","Sakallı bir adam elini tahtanın üzerine uzatıyor."],["Sağdaki adam","Rakibi, koltukta tahtaya eğilmiş; ayaktaki kadın onu yarı yarıya kapatıyor."],["Ayaktaki kadın","Elini çenesine dayamış, oyunu izliyor."],["Lamba","Duvarın yanında bir lamba. Duvar kâğıdı da döşeme de desenle dolu."],["Kurşun kalem notu","Sol altta kurşun kalemle: “partie de dames” — bir dama oyunu."]]},"talbot":{"title":"Satranç Oyuncuları (erken dönem fotoğraf)","artist":"William Henry Fox Talbot’a atfedilir","date":"y. 1843–47","place":"İngiltere","game":"Satranç","medium":"Tuzlu kâğıt baskı","size":"19,9 × 15 cm","credit":"Bay ve Bayan Everett Kovler’in fonuyla satın alındı","p":["Talbot’un icat ettiği negatif-pozitif yöntemi, mümkün kıldığı sınırsız kopyalarla, dijital çağa dek fotoğrafa hâkim oldu. İlk deneyleri hem bilime ilgisini hem sanatsal hedeflerini gösterir; araştırmacılar onun satranç oyuncularını en az on kez fotoğrafladığını doğrulamıştır.","Ama bu kare onun olmayabilir: bu baskı ve aynı sahnenin diğerleri imzasızdır ve Talbot’un alışık olduğu kâğıttan farklı bir kâğıda basılmıştır. Oturanlar büyük olasılıkla fotoğrafçı Antoine Claudet ile Talbot’un yardımcısı Nicolaas Henneman’dır; yeni araştırmalara göre görüntüler Claudet’nin stüdyosunda çekilmiş, Henneman’a geçmiş ve bir borcun karşılığı olarak Talbot’a verilmiştir (müze notu)."],"spots":[["Tahta","Masadaki satranç tahtası, taşlar sıra sıra."],["Silindir şapkalı adam","Şapkası başında, bir taşa uzanıyor."],["Düşünceli adam","Eli çenesinde, rakip tahtayı inceliyor."],["Perde","Arkada asılı bir perde — çekim için bir fon mu?"],["Bir şapka daha","Sağdaki sehpada ikinci bir silindir şapka duruyor."]]},"pvl":{"title":"Zar Oynayan Adamlar","artist":"Usta PVL","date":"y. 1520","place":"Hollanda (Alçak Ülkeler)","game":"Zar","medium":"Kâğıt üzerine gravür","size":"9,4 × 9,4 cm (yuvarlak)","credit":"Charles Hack ve Hearn Ailesi Vakfı Koleksiyonu, 2023’te satın alındı","p":["16. yüzyıl başında Alçak Ülkeler’de çalışmış adı bilinmeyen bir gravürcünün eseri; sol altta kazınmış “PVL” monogramından ötürü Usta PVL diye anılır. Avuç içine sığacak kadar küçük yuvarlak baskıda sık, ince çizgiler odanın derinliğini ve giysilerin dokusunu kurar.","Masada iki zar var. Öne eğilmiş bir adam ile kürk yakalı bir genç parmakla gösterip tartışıyor — belki sayı üzerine. Arkada kadınlar izliyor, masanın altında bir şarap testisi duruyor. Zar, antik çağdan beri kumarla bağlantılıdır ve tekrar tekrar yasaklanmıştır."],"spots":[["Zarlar","Masada yuvarlanan iki zar."],["Gösteren eller","İki parmak masada buluşuyor — sayı üzerine bir tartışma mı?"],["Geniş şapkalı adam","Öne eğilmiş; yırtmaçlı kabarık kolları dönemin modasıydı."],["Kürk yakalı genç","Büyük şapkalı, kürk yakalı bir genç."],["İzleyen kadınlar","Kadınlar arkadan oyuna bakıyor."],["Monogram","Sol alttaki “PVL” — sanatçının adına dair tek ipucu."]]},"kiyohiro":{"title":"Sugoroku Oyuncuları","artist":"Torii Kiyohiro","date":"y. 1750","place":"Japonya (Edo dönemi)","game":"Ban-sugoroku","medium":"Renkli ağaç baskı (benizuri-e), ōban; yayımcı Urokogataya","size":"43,5 × 29,3 cm","credit":"Clarence Buckingham Koleksiyonu","p":["Torii Kiyohiro, yaklaşık 1737–1776 arasında çalışmış bir ukiyo-e sanatçısıdır. Bu bir benizuri-e’dir: tam renkli nishiki-e’lerin 1765’te ortaya çıkmasından önceki yıllarda, pembe beni ve yeşil gibi az sayıda renk kalıbıyla basılmıştır.","Siyah ayaklığın üzerindeki oyun ban-sugoroku’dur: iki oyuncu zar atıp beyaz ve siyah taşları ilerletir, taşlarının hepsini önce çıkaran kazanır. Tavla ile aynı aileden bir oyundur ve ukiyo-e baskıları kadınları bu oyunla sıkça gösterir. Arkada bir kadın uzun bir pipo içerek izliyor."],"spots":[["Tahta","Ayaklığı üzerinde, beyaz ve siyah taşlı bir sugoroku tahtası."],["Soldaki figür","Bir taşı oynatmak için uzanıyor."],["Sağdaki kadın","Tahtaya eğilmiş rakip taşları inceliyor."],["Pipolu kadın","Uzun kiseru pipesiyle oyunu arkadan izliyor."],["Kalkık el","Sağdaki kadın küçük, siyah bir şey tutuyor — zar kabı mı?"],["İmza","“Torii Kiyohiro hitsu” imzası ve yayımcı Urokogataya’nın mührü."]]},"ingram":{"title":"Çin Satrancı Oyunu","artist":"John Ingram, François Boucher’den","date":"1741–63","place":"Fransa (Paris)","game":"Xiangqi","medium":"Asitle oyma ve gravür","size":"Kâğıt 39,4 × 27,7 cm (kalıp 24,5 × 16,4 cm)","credit":"Elisha Whittelsey Koleksiyonu, 1966","p":["Fransız ressam François Boucher’in bir çizimi, Londra doğumlu gravürcü John Ingram tarafından oyulmuştur. Ingram Paris’e taşınmış ve 1741–1763 arasında Boucher’in şinuazrilerinden — Avrupalıların hayal ettiği Çin’den — bir dizi baskı yapmıştır. Alttaki başlık “LE JEU D'ECHETS CHINOIS”, yani Çin satrancı oyunudur.","Saçları yüksekte toplanmış bir kadın kucağındaki tahtada bir taşı oynatıyor, küçük bir çocuk da izliyor. Oyunun xiangqi olduğu kabul edilir; ama gerçek xiangqi taşları hep yassı disklerdir, burada ise uzun taşlar küçük kare taşların yanında duruyor. Palmiye ve küpün üstünde oturan figür de gerçek Çin’den çok, dönemin Avrupa’sının düşlediği uzak ülkeye aittir."],"spots":[["Tahta ve taşlar","Kucağındaki tahta; uzun ve kare taşlar. Gerçek xiangqi taşları yassı disklerdir."],["Taştaki el","Sağ eli bir taşı oynatıyor."],["Elde yanak","Sol eli çenesinde, tahtaya bakıyor."],["İzleyen çocuk","Tahtanın yanında duran çocuk oyunu izliyor."],["Küpün üstündeki figür","Büyük bir küpün üstünde bağdaş kurmuş bir figür."],["Başlık ve adlar","“Dessiné par Fr. Boucher”, “Gravé par Ingram” ve başlık “LE JEU D'ECHETS CHINOIS”."]]},"posada":{"title":"Kaz Oyunu","artist":"José Guadalupe Posada","date":"1909","place":"Meksika","game":"Kaz oyunu","medium":"Kâğıt üzerine çinko kabartma baskı","size":"29,3 × 39,4 cm","credit":"William McCallin McKee Memorial Endowment","p":["İskelet “calavera”larıyla ünlü Meksikalı gravürcü Posada’nın, Mexico City’deki yayımcı Antonio Vanegas Arroyo için yaptığı, üzerinde oynanan tek yapraklık bir baskı. Sol alttaki şeritte “JUEGO DE LA OCA” (kaz oyunu) yazar; yol 1 numaralı kareden merkezdeki 63’e sarmal çizerek ilerler.","Ortada kurallar (EXPLICACION) basılıdır: ilk atışta 5 ve 4 gelirse 26’ya, 6 ve 3 gelirse 53’e gidilir. Kaza (bir kuşa) gelen aynı sayıyı bir kez daha sayar; handa (Venta, 19) iki el beklenir; kuyuda (Poso, 31) ve hapishanede (Carcel, 52) başkası gelene dek kalınır; labirent (42) 39’a, ölüm (Muerte, 58) başa geri gönderir. 63’e tam olarak gelmek gerekir. Bazı karelerde bahis ödenirdi: bu aynı zamanda bir kumar oyunuydu."],"spots":[["Kurallar","Ortadaki “EXPLICACION”: her karenin etkisi ve bahsin ne zaman ödeneceği."],["1 numaralı kare","Başlangıç. Buradan yol sarmal çizerek merkeze gider."],["Kuyu (31)","Çeşmeye benzeyen bir kuyu. Düşen, başkası gelene dek kalır."],["Ölüm (58)","Kafatası karesi: başa dönülür."],["Başlık şeridi","Sol alttaki şeritte “JUEGO DE LA OCA”; altında çocuklar oynuyor."],["Yayımcının adı","Tanrıçanın şeridinde “IMPRENTA DE A. VANEGAS ARROYO” — Posada’nın pek çok baskısını yayımlayan basımevi."]]},"jintile":{"title":"Masa oyunu oynayan kadınlı karo","artist":"Bilinmiyor","date":"13. yüzyıl","place":"Çin (Jin hanedanı)","game":"Masa oyunu (büyük olasılıkla go)","medium":"Pişmiş toprak (kalıp kabartma)","size":"Yük. 27,3 cm, gen. 24,8 cm, der. 5,4 cm","credit":"Friends of Asian Art bağışlarıyla satın alındı, 2002","p":["Kuzey Çin’i yöneten Jurçen halkının hanedanı Jin (1115–1234) döneminde yapılmış kabartmalı bir karo. Çiçekli bir ağacın altında iki kadın bir sekinin üzerinde karşılıklı oturuyor, aralarında bir tahta var.","Tahtada ince bir ızgara var; büyük olasılıkla go oynuyorlar. Sağdaki kadın öne eğilip tahtayı işaret ediyor, soldaki izliyor. Kuzey Çin’deki Jin dönemi mezarlarının pek çoğu gündelik yaşam sahneli kabartma tuğlalarla kaplanırdı; bu karo da büyük olasılıkla böyle bir mezarı süslüyordu."],"spots":[["Tahta","İnce ızgaralı bir tahta, büyük olasılıkla go tahtası."],["İşaret eden el","Sağdaki kadın tahtayı işaret ediyor. Sıradaki hamlesi mi?"],["Soldaki kadın","Saçları yukarıda toplanmış, tahtaya bakıyor."],["Sağdaki kadın","Tahtaya doğru eğilmiş."],["Çiçekli ağaç","Üstlerinde çiçekli bir ağacın dalları uzanıyor."],["Seki","Oturdukları seki; ayakları arasında dalgalı bir süs var."]]},"kyosai":{"title":"Bir yellenme go oyununu altüst ediyor (bir eskiz albümünden)","artist":"Kawanabe Kyōsai","date":"19. yüzyılın ortası–sonu","place":"Japonya (Edo–Meiji dönemi)","game":"Go","medium":"26 çift yapraklı akordeon albümün bir açılımı; kâğıt üzerine mürekkep ve renk","size":"Albüm (kapalı) 28 × 18 cm","credit":"Anne ve Anthony d’Offay bağışı, Evan Turner onuruna","p":["Şogunluğun son yıllarından Meiji dönemine kadar çalışmış ressam Kawanabe Kyōsai’nin (1831–1889) eskiz albümünden bir sahne; katlanır bir albümün sayfalarına hızlı, serbest fırça darbeleriyle çizilmiş. Kanō okulunun titiz tekniğiyle yetişen Kyōsai, cinleri, karikatürleri ve hicivleriyle de sevilirdi.","Müzenin verdiği ad her şeyi anlatıyor: “Bir yellenme go oyununu altüst ediyor.” Solda siyah başlıklı bir adam eğiliyor; sağda tahta havaya uçuyor, kaplardan taşlar yağmur gibi dökülüyor, rakip sırtüstü devriliyor. Ciddi bir oyun tek bir patlamayla mahvoluyor: Kyōsai, ortaçağ tomarlarında bile görülen eski Japon yellenme mizahını hızlı fırçasıyla resmediyor."],"spots":[["Siyah başlıklı adam","Eğilmiş, kalçasını çıkarmış — kargaşanın sebebi mi?"],["Uçan tahta","Çizgili go tahtası çapraz uçup gidiyor."],["Kaplar ve taşlar","İki kap devriliyor, taşlar yağıyor."],["Yelpaze","Tahtanın yanında açık bir yelpaze de uçuyor."],["Devrilen rakip","Sırtüstü yatmış, gözleri faltaşı gibi açık."],["Fırça çizgisi","Taslaksız, bir çırpıda çekilmiş gibi güçlü mürekkep çizgileri."]]},"yokuts":{"title":"Kumar Tepsisi","artist":"Yokuts dokumacı (adı bilinmiyor)","date":"y. 1900","place":"ABD (Dunlap yakını, Kaliforniya)","game":"Huuchuish (ceviz kabuğu zarlar)","medium":"Bitki lifleri (sarmal örgü)","size":"Yük. 5,1 cm, çap 61 cm","credit":"Bayan Leonard S. Florsheim Jr.’ın fonuyla satın alındı","p":["Kaliforniya’nın pek çok yerli halkı şans oyunları oynardı. Bu tepsi, yalnızca kadınların oynadığı bir zar oyunu olan huuchuish için kullanılırdı: sekiz ceviz kabuğu zar tepsiye atılır, puanlar çubuklarla sayılırdı.","Tepsiye dokunmuş dairesel desen oyunun kendisini gösterir — zarları, sayı çubuklarını ve oyuncuları (müze notu). Kendi oyununun resmini taşıyan bir oyun aracıdır. Fotoğrafta ceviz kabuğu zarlar tepsinin üstünde ve çevresinde duruyor."],"spots":[["Oyuncular","Kenar boyunca dizilen figürler — oyuna katılanlar."],["Sayı çubukları","Kısa dikey çizgi demetleri: puan sayan çubuklar."],["Yuvarlak motifler","Küçük yuvarlak motifler — zarlar mı?"],["Ceviz zar","Ceviz kabuğundan bir zar. Sekizi tepsiye atılırdı."],["Üçgen kuşak","Koyu üçgenlerden bir kuşak çepeçevre dolanır."],["Merkez","Örgü merkezden sarmal çizerek çıkar; çevresinde kesikli bir halka var."]]},"hokkei":{"title":"Ushiwakamaru, Benkei’yi sugoroku’da yeniyor","artist":"Totoya Hokkei","date":"y. 1825","place":"Japonya (Edo dönemi)","game":"Ban-sugoroku","medium":"Surimono (renkli ağaç baskı, shikishiban)","size":"21,8 × 19,1 cm","credit":"Helen C. Gunsaulus bağışı","p":["Hokusai’nin öğrencisi Totoya Hokkei’nin (1780–1850) bir surimonosu. Surimonolar özel olarak — çoğu zaman şiir çevrelerince, kendi dizeleriyle — sipariş edilen ve ticari ukiyo-e’den daha gösterişli, iyi kâğıt ve metalik pigmentlerle basılan baskılardı.","Kahraman Minamoto no Yoshitsune’nin çocukluk adı Ushiwakamaru ile dev savaşçı keşiş Benkei. Ünlü karşılaşmaları Kyoto’daki Gojō Köprüsü’ndeki düellodur; burada ise mücadele bir sugoroku oyununa dönüşüyor: çocuk tahtanın ardında sakin oturuyor, sırtında teber taşıyan Benkei yenilgiyle başını kaşıyor. Oyunbaz bir yeniden yorum gibi görünüyor."],"spots":[["Sugoroku tahtası","Beyaz ve siyah taşlı, kutu biçimli bir tahta."],["Başını kaşıyan Benkei","Tam zırhlı, yenilen Benkei başını kaşıyor."],["Ushiwakamaru","Tahtanın ardında oturan genç kahraman."],["Teber","Benkei’nin büyük naginatasının ağzı."],["Şiir","Sağ üstteki dizeler — büyük olasılıkla baskıyı sipariş eden çevreden."],["İmza","Sağ alttaki çerçevede Hokkei’nin imzası."]]},"vorsterman":{"title":"Tavla Oyuncuları (gece sahnesi)","artist":"Lucas Emil Vorsterman, Adam de Coster’den","date":"y. 1630","place":"Flandre (Anvers)","game":"Tavla","medium":"Fildişi rengi kâğıt üzerine gravür","size":"Görüntü 25,5 × 34,4 cm","credit":"Bernard F. Rogers Koleksiyonu","p":["Adam de Coster, 1630 dolaylarında Anvers’te mum ışığında gece sahneleriyle tanınan bir ressamdı; aynı dönemde aynı kentte Vorsterman, popüler çağdaşlarının eserlerini gravüre aktarıyordu. Rubens’in öğrencisi olan Vorsterman ustasıyla bozuşup İngiltere’ye gittikten sonra, bunun gibi daha güçlü, üslupçu, Caravaggio tarzı gravürler yaptı.","Karanlık bir odada bir masanın çevresinde adamlar tavla tahtasının başına toplanmış. De Coster’in ışık kullanımını izleyerek iki mum alevi masadaki yüzleri aydınlatıyor (müze notu). Sağda lavtalı bir genç bize bakıyor."],"spots":[["Tahta","Masada kutu gibi açılmış bir tavla."],["Mum","Şamdandaki mum; alevi yüzleri aydınlatıyor."],["Pipolu adam","Geniş şapkalı, pipo içerek oyunu izliyor."],["Arkası dönük adam","Ellerini masaya dayamış, öne eğilmiş."],["Lavtacı genç","Lavtasıyla bize gülümseyen bir genç."],["Adlar","Sol altta “A. De Coster pi.”, sağ altta “Vorsterman”."]]},"zorn":{"title":"Satranç Oyuncuları","artist":"Anders Zorn","date":"1891","place":"İsveç","game":"Satranç","medium":"Fildişi rengi vergé kâğıt üzerine asitle oyma","size":"Görüntü 13,5 × 9,6 cm (kalıp 13,9 × 10 cm)","credit":"Wallace L. DeWolf ve Charles Deering’in Anders Zorn asitle oyma koleksiyonları","p":["İsveçli sanatçı Anders Zorn’un (1860–1920) bir asitle oyması. Zorn yağlıboya ve suluboya portreleriyle uluslararası ün kazanmış, gravürde de büyük bir iş bırakmıştır. Kalıp bir avuç büyüklüğündedir.","Üst üste atılmış hızlı, eğik çizgiler, bakırdan karanlık bir oda ve iki insan çıkarmaya yetiyor. Öndeki adam sırtı bize dönük, tahtaya eğiliyor; karşıdaki figür başını eğmiş, sonraki hamleyi düşünüyor. Taşlar ince çizgilerle çizilmiş. Kimlerin poz verdiği bilinmiyor."],"spots":[["Tahta ve taşlar","Alttaki açık alan tahta; kısa dikey çizgiler taşlar."],["Öndeki adam","Sırtı bize dönük, tahtaya eğilmiş."],["Rakip","Başı eğik, gözleri tahtada."],["Karanlık fon","Dikey çizgilerle kurulmuş odanın derinliği."],["Eğik çizgiler","Ceket, üst üste atılmış hızlı çapraz çizgilerden."],["İmza","Kalıbın altında kurşun kalemle “Zorn” imzası."]]},"harunobu-sugoroku":{"title":"Oyunu İzlemek (sugoroku)","artist":"Suzuki Harunobu","date":"y. 1766","place":"Japonya (Edo dönemi)","game":"Ban-sugoroku","medium":"Renkli ağaç baskı (chūban, surimono)","size":"28,5 × 21 cm","credit":"Clarence Buckingham Koleksiyonu","p":["Suzuki Harunobu (1725?–1770), birçok kalıpla basılan tam renkli nishiki-e baskıları 1765 dolaylarında doğduğunda merkezdeki isimdi. Bu, özel olarak basılmış bir surimonodur; yumuşak, katmanlı renkleri yeniliği gösterir.","Erik çiçekli bir odada iki genç kadın kutu biçimli bir sugoroku tahtasında oynuyor, üçüncüsü ayakta tahtaya bakıyor. Tahtada beyaz ve siyah taşlar dizili; soldaki bir taş oynatıyor, sağdaki tahtaya uzanıyor. Arkadaki sürgülü kapıda şelale ve çamlar resmedilmiş."],"spots":[["Sugoroku tahtası","Beyaz ve siyah taşlı, kutu biçimli bir ban-sugoroku tahtası."],["Soldaki genç kadın","Kâğıt turnalı kimonosuyla bir taş oynatıyor."],["Sağdaki genç kadın","Eğilmiş, tahtaya uzanıyor."],["İzleyen","Ayakta oyuna bakıyor; elinde uzun saplı bir nesne var."],["Erik","Yukarıdan dallarını uzatan beyaz bir erik."],["Resimli kapı","Şelale ve çamlarla bezeli sürgülü kapı."]]},"kota":{"title":"Kota Mihracesi Kishor Singh II, Krishna’ya Brij Rajji olarak tapınırken","artist":"Bilinmiyor","date":"y. 1825","place":"Hindistan (Racastan, Kota)","game":"Pachisi","medium":"Kâğıt üzerine zamklı tempera, gümüş ve altın","size":"24,5 × 18,8 cm","credit":"James Albert and Mary Gardiner Ford Memorial Fund","p":["Küçük Kota prensliğinin hükümdarı (hd. 1819–28), Pushti Marg tarikatının rahibi kılığında, beş alevli bir kandil sunuyor. Sunaktaki küçük mabette, iki eşiyle birlikte Krishna’nın metal tasvirleri duruyor — yalnızca Kota’da tapınılan bir ikon.","Tavandan pek çok cam lamba sarkıyor; sunağa çıkan basamaklarda Krishna’yı ve arkadaşlarını eğlendirecek oyuncaklar ve oyunlar dizili: pirinç filler, gümüş inekler, toplar ve bir pachisi tahtası (müze notu). Kırmızı haç biçimli bez o tahtadır — tanrıya oyuncak olarak sunulmuş pachisi."],"spots":[["Pachisi tahtası","Basamaklardaki kırmızı haç biçimli bez: bir pachisi tahtası."],["Filler","Tahtanın yanında iki pirinç fil."],["Toplar","Üst basamakta altın renkli toplar."],["Krishna","Küçük mabetteki Krishna ve iki eşinin tasvirleri."],["Hükümdar ve kandil","Rahip kılığında beş alevli kandil sunuyor."],["Cam lambalar","Tavandan sarkan çok sayıda cam lamba."]]},"coyote":{"title":"Çakal Oyunu","artist":"José Guadalupe Posada’nın bir takipçisi","date":"Tarihsiz","place":"Meksika","game":"Çakal ve tavuklar (tilki ve kazlar ailesinden)","medium":"Kâğıt üzerine çinko kabartma baskı","size":"38,2 × 30,5 cm","credit":"William McCallin McKee Memorial Endowment","p":["Posada’nın Mexico City’deki halk matbaaları için yaptıkları gibi çinko kabartmayla basılmış, üzerinde oynanan tek yapraklık bir baskı. Üstte “JUEGO DEL COYOTE” (çakal oyunu) yazar; çevrede çakallar kümese saldırıyor, bir adam da birini kovmak için sopa sallıyor. Alttaki şeritte “Ildefonso T. Orellana’nın mülküdür” yazar.","Kurallar alttaki “EXPLICACION”da basılıdır: iki kişi oynar; birinde on beş tavuk, ötekinde tek bir çakal vardır. Tavuklar ileri ya da yana gider ama asla geri dönmez; çakal her yöne gider ve arkası boşsa bir tavuğun üzerinden atlayarak onu yer. Tavuklar çakalı kıstırırsa kazanır. Avrupa’daki tilki ve kazlar ile aynı av oyunudur."],"spots":[["Çakalın yeri","Ortadaki dairede çakal başı: çakal buradan başlar."],["Tavukların yerleri","Tavuk resimli daireler: taşlar buraya dizilir."],["Kurallar","“EXPLICACION”: taşlar, hamleler ve kazanma."],["Başlık","“JUEGO DEL COYOTE” — çakal oyunu."],["Tavuğa saldıran çakal","Sol altta bir çakal bir tavuğa saldırıyor."],["Sopalı adam","Sağ üstte bir adam bir çakala sopa kaldırıyor."]]},"mons":{"title":"Mons (Bergen) Üzerine Tavla, 1709","artist":"Pieter Nolpe (kalıp ve yayımcı)","date":"Kalıp 1623–53; baskı y. 1709","place":"Hollanda (Amsterdam)","game":"Trictrac (tavla ailesinden)","medium":"Asitle oyma, gravür ve dizgi şiir","size":"Kâğıt 35,8 × 18,6 cm (kalıp 12,9 × 17,5 cm)","credit":"","p":["Dört adam bir masada trictrac oynuyor. Müze kaydına göre A–D harfleri Marlborough Dükü, Bavyera Prens Seçicisi, Ouwerkerk Lordu ve Villeroy Dükü’nü gösterir. Müttefiklerin 1709’da Mons’u (Felemenkçede Bergen) Fransızlardan kuşatıp almasını, kentin ortaya konduğu bir tavla oyunu olarak hicveden bir baskıdır. Arka odada (E) İspanya Kralı V. Felipe bir kadınla birliktedir.","Kalıpta yapımcı ve yayımcı olarak Pieter Nolpe’nin imzası var; ama Nolpe 1650’lerin başında öldüğüne göre, 17. yüzyıldan kalma eski bir kalıp harfler ve yeni bir şiir eklenerek yeniden basılmış olmalı. Alttaki şiir, büyük beylerin oyununun hep tiktak ve verkeer (bu aileden iki oyun) olduğunu söyleyerek başlar, sonra her oyuncuyla tek tek alay eder."],"spots":[["Tahta","Masadaki trictrac: ortaya konan bir kent."],["A, Marlborough","Ayakta tahtaya bakıyor — Müttefiklerin İngiliz komutanı."],["B, Bavyera Prens Seçicisi","Şapkasız, sandalyesine gömülmüş."],["C, Ouwerkerk","Tüylü şapkalı — Hollandalı general."],["E, arka oda","Arkadaki yatak odasında bir kadınla V. Felipe."],["Şiir","Altta basılı Felemenkçe şiir; A’dan E’ye oyuncularla alay ediyor."]]},"stembus":{"title":"Sandık: Siyasi Bir Kaz Oyunu","artist":"Johan Michaël Schmidt Crans (baskıcı)","date":"1867","place":"Hollanda","game":"Kaz oyunu (hiciv)","medium":"Taş baskı","size":"66 × 50 cm","credit":"","p":["Kaz oyunu biçiminde hicivli bir baskı. De Nederlandsche Spectator haftalık dergisinin 2 Mart 1867 tarihli 9. sayısıyla, ayrı bir kural yaprağıyla birlikte çıkmıştır (müze kaydı). Karelerde dönemin bakanlarının portreleri var.","Oyun Lahey’deki parlamento binası Binnenhof’ta başlar ve ortada 64. kare “Insulinde”de — Hollanda Doğu Hint Adaları’nın şiirsel adı — biter; orada Cava adasına asılmış bakan Pieter Mijer’in portresi bekler. Mijer sömürgeler bakanlığından Doğu Hint genel valiliğine geçmişti ve bu atama siyasette fırtına koparmıştı. Olağan 63’ten bir fazla olan kare, büyük olasılıkla bu son espri içindir."],"spots":[["Başlangıç","Sol üstteki bina: oyun Lahey’deki Binnenhof’ta başlar."],["Mijer’in portresi","63. kare: Pieter Mijer’in çerçeveli portresi iplerle adaya asılı."],["Insulinde 64","Ortadaki ada ve 64 sayısı: bitiş."],["Sandık","Sağ alttaki “DE STEMBUS” (sandık): başlıktaki kutu."],["Bakanlar","Karelerden dönemin bakanlarının yüzleri bakıyor."],["Horoz","Bir karedeki horoz; neyi alaya aldığı bilinmiyor."]]},"koorai":{"title":"Bir Masa Oyunu Başında Koreliler (Siebold’un Nippon’undan)","artist":"James Erxleben (taşbaskıcı), “Toioske”nin çiziminden","date":"1832–52","place":"Hollanda (Leiden) / Koreliler","game":"Masa oyunu (büyük olasılıkla go)","medium":"Tonlu taşbaskı, elle boyanmış","size":"Kâğıt 38 × 55,5 cm","credit":"F. G. Waller bağışı","p":["Alman doğumlu hekim Philipp Franz von Siebold’un Nagasaki’deki Hollanda ticaret karakolunda (1823–30) gördüklerine dayanarak Leiden’de yayımladığı büyük eser NIPPON’dan bir levha. Sağ üstte “TAB. I”, altta “KOORAI” (Kore) ve Felemenkçe ile Almanca “bir balıkçı ailesi” yazar. Taşa Erxleben çizmiş; levha çizeri “Toioske” olarak anar.","Dört adam yere oturmuş bir tahtanın çevresinde; solda bir kadın küçük bir çocuğu elinden tutuyor, sağda uzun bir sopa ve kese tutan bir adam ayakta. Önde yerde geniş kenarlı siyah bir şapka (gat) var. Tahtada ızgara ve yuvarlak taşlar görülüyor; büyük olasılıkla go (Korecede baduk), ama kayıtta yalnızca “bir masa oyunu” denir."],"spots":[["Tahta","Izgara ve yuvarlak taşlar: büyük olasılıkla bir go oyunu."],["Siyah şapka","Yerde geniş kenarlı siyah bir şapka (gat)."],["Anne ve çocuk","Elinde çocukla oyunu izleyen kadın."],["Ayaktaki adam","Uzun sopa ve keseyle ayakta duran adam."],["Eğilen adam","Mavi ceketli, tahtaya bakıyor."],["Başlık","“KOORAI” (Kore) ve Felemenkçe ile Almanca “bir balıkçı ailesi”."]]},"cairo":{"title":"Bir Kahvenin Önünde Masa Oyunu Çevresindekiler (Kahire)","artist":"Délié & Béchard (Hippolyte Délié ve Émile Béchard)","date":"y. 1869–90","place":"Mısır (Kahire)","game":"Masa oyunu (büyük olasılıkla satranç)","medium":"Albümin baskı","size":"10,8 × 16,4 cm","credit":"","p":["Kahire’de stüdyo işleten Fransız fotoğrafçılar Hippolyte Délié ve Émile Béchard’ın bir fotoğrafı. Kartonda stüdyonun adı, “Ezbekiye Bahçesi yanında”, ve “Kahire (Mısır)” basılıdır. Mısır’a gelen yolcular bu tür fotoğrafları hatıra olarak alırdı.","Kafesli pencereli bir dükkânın önünde yere oturmuş adamlar alçak bir sehpadaki tahtanın çevresinde. Tahtada uzun taşlar duruyor; büyük olasılıkla satranç (Arapçada şatranç), ama müze kaydında yalnızca “bir masa oyunu” denir. Uzun pozlama için herkes kıpırdamadan duruyor."],"spots":[["Tahta ve taşlar","Alçak sehpadaki tahta, uzun taşlarla: büyük olasılıkla satranç."],["Kafesli pencere","Ahşap kafesli pencere; eski Kahire evlerine özgü."],["Sopalı adam","Elinde sopa, oturmuş oyunu izliyor."],["Sepet","Yerde örme bir sepet."],["İzleyen çocuk","Arkadan tahtaya bakan bir çocuk."],["Stüdyonun adı","Kartondaki “AU JARDIN DE L’ESBÉKIEH” ve “CAIRE (EGYPTE)”."]]},"vanmour":{"title":"İskambil Oynayan Ermeni Topluluğu","artist":"Jean-Baptiste Vanmour","date":"y. 1720–37","place":"Osmanlı İmparatorluğu (İstanbul)","game":"İskambil","medium":"Tuval üzerine yağlıboya","size":"44,5 × 58,5 cm","credit":"","p":["Flandre doğumlu Vanmour 1699’da Fransız elçisiyle İstanbul’a geldi ve ölene dek bu şehirde yaşayarak saray törenlerini ve halkın gündelik hayatını resmetti. Müze, erkeklerin giysilerinden Ermeni oldukları anlaşıldığını belirtir.","Büyük bir mumun ışığında kadınlı erkekli bir grup, kırmızı örtülü bir masanın çevresinde iskambil oynuyor. Masada dağıtılmış kâğıtlar var, bazıları elindeki kâğıtlara bakıyor. Sol köşede yaşlı bir kadın iplik eğiriyor. Kayıtta hangi oyun olduğu yazmıyor."],"spots":[["Masadaki kâğıtlar","Kırmızı örtülü masadaki iskambil kâğıtları."],["Büyük mum","Tüm topluluğu tek bir mum aydınlatıyor."],["İplik eğiren yaşlı kadın","Sol köşede iplik eğiren yaşlı kadın."],["Elindeki kâğıtlara bakan kadın","En sağda kâğıtlarına bakan bir kadın."],["Kürklü adam","Kürk kenarlı kaftanlı adam; giysileri Ermeni olduklarını gösterir."],["Masaya uzanan","Elinde kâğıtlarla masaya eğilen biri."]]},"algiers":{"title":"Masa Oyunu Oynayan Üç Adam (Cezayir)","artist":"Anonim","date":"1851–1900","place":"Cezayir (Cezayir kenti)","game":"Masa oyunu (büyük olasılıkla tavla)","medium":"Albümin baskı","size":"14,0 × 10,0 cm","credit":"","p":["Görüntünün altına el yazısıyla “Alger” (Cezayir) yazılmış, fotoğrafçısı bilinmeyen bir fotoğraf. Düz bir fonun önüne sandalyeler ve küçük bir masa konduğundan büyük olasılıkla stüdyoda çekilmiştir. Kuzey Afrikalıları gösteren bu tür fotoğrafları yolcular ve koleksiyoncular alırdı.","İki adam kenarlı bir tahtanın iki yanında karşılıklı oturuyor; sağdaki bir pula uzanıyor. Tahtada üst üste yuvarlak pullar var; büyük olasılıkla tavla, ama kayıtta yalnızca “bir masa oyunu” denir. Öndeki küçük masada kahve takımı duruyor."],"spots":[["Tahta ve pullar","Kenarlı bir tahta, üzerinde üst üste yuvarlak pullar."],["Ayaktaki seyirci","Belinde kuşak, arkada ayakta oyunu izleyen adam."],["Soldaki yaşlı","Başı sarılı, düşünceli yaşlı adam."],["Sağdaki adam","Başında beyaz örtü, tahtaya eğilmiş adam."],["Kahve takımı","Oymalı küçük masada tepsi ve fincanlar."],["Pulu süren el","Sağdaki oyuncunun pula uzanan eli."]]},"circo":{"title":"Sirk Oyunu (Juego del Circo)","artist":"Manuel Manilla (?)","date":"Tarihsiz","place":"Meksika","game":"İki zarla oynanan bahis oyunu","medium":"Kabartma baskı (uç ağaç ya da fotoğrafik kabartma) ten rengi kâğıt üzerine","size":"26,2 × 35,0 cm","credit":"","p":["Soru işaretiyle Meksikalı baskıcı Manuel Manilla’ya atfedilen bir oyun kâğıdı. Sağ altta satıcısı olan “El Teatro” baskıevinin adı ve adresi yazılı. Bu tür ucuz baskılar sokakta satılır ve anlaşılan olduğu gibi üzerinde oynanırdı.","Ortada bir sirk çadırı, çevresinde atlı akrobatlar, insan kulesi, güçlü adam ve başkaları; her birinde 2’den 12’ye bir sayı var. Sol üstteki “Açıklama”ya göre herkes, çocuklar da oynayabilir: iki zar atılır, gelen sayının karesine bahis konur ya da orada olan bahis alınır. 12 atan her şeyi alır."],"spots":[["Sirk çadırı","“JUEGO DEL CIRCO” başlığı ve 12 numaralı kare olan çadır."],["Oyun kuralları","“ESPLICACION” başlıklı kurallar."],["Atlı akrobat","Dörtnala koşan atın sırtında dansçı: 6 numara."],["İnsan kulesi","Birinin omzunda duran adam: 4 numara."],["Güçlü adam","Top biçimli bir ağırlık kaldıran adam: 8 numara."],["Baskıevinin adı","“De venta, Estampería ‘El Teatro’” ve adres."]]},"loteria":{"title":"Lotería Resimli Kartları","artist":"José Guadalupe Posada","date":"1880–1913","place":"Meksika","game":"Lotería (resim çağırma oyunu)","medium":"Kabartma baskı (uç ağaç ya da fotoğrafik kabartma) ten rengi kâğıt üzerine","size":"30,0 × 40,0 cm","credit":"","p":["Meksikalı baskıcı Posada, haber, şarkı ve oyun taşıyan ucuz basmalar çıkaran Mexico City’li yayıncı Antonio Vanegas Arroyo için sayısız resim çizdi. Bu kâğıtta da “JUEGO DE LOTERIA” başlığı ve Vanegas Arroyo’nun adı basılı.","Kâğıdı adı yazılı otuz sekiz küçük resim dolduruyor: yıldız, ay, akrep, şeytan, kurukafa, horoz, matbaa ve daha fazlası. Tombalaya benzeyen lotería’da çağıran kişi kart çekip resmin adını söyler, oyuncular kendi levhalarındaki o resmi fasulye gibi şeylerle işaretler. Kâğıt büyük olasılıkla kesilip kart yapılırdı."],"spots":[["Başlık ve yayıncı","“JUEGO DE LOTERIA” ve Vanegas Arroyo’nun dükkânının adı."],["Yıldız","“ESTRELLA”, sol üstteki ilk resim."],["Ay","“LUNA”, yüzlü bir hilal."],["Ölüm","“MUERTE”: tırpanlı, kaval çalan bir iskelet."],["Tlachiquero","“TLACHIQUERO”: agav özü toplayan adam."],["Matbaa","“IMPRENTA”: preste çalışan işçiler; bu tür kâğıtların basıldığı yer."]]},"jeupol":{"title":"“Jeu polonais”, yani Dama Tahtası","artist":"Anonim","date":"1833–1900","place":"Belçika ya da Hollanda","game":"Dama (10 × 10 tahta)","medium":"Ağaç baskı, matbaa harfli metin","size":"32,2 × 39,6 cm","credit":"","p":["Üstünde Fransızca ve Felemenkçe “JEU POLONAIS OF DAMSPEL” başlığı basılı tek yaprak. “Jeu polonais” (Leh oyunu), Fransa’da 10 × 10 tahtada oynanan damaya verilen addı. Sağ üstte yayıncının sıra numarası “n. 106” var.","Müze kaydında dendiği gibi 50 beyaz, 50 siyah, toplam 100 kare var; sağda ve solda süslü kenarlar. Taşlar basılmamış; büyük olasılıkla fasulye ya da düğmeyle, kâğıdın üstünde oynanan ucuz bir tahtaydı. Kâğıtta katlama izleri duruyor."],"spots":[["Başlık","“JEU POLONAIS OF DAMSPEL” yazısı."],["Sıra numarası","Yayıncı numarası “n. 106”."],["Sol kenar","Yuvarlak çiçek motiflerinden bir sütun."],["Sağ kenar","Öbür yanda aynı desen."],["Yüz kare","10 × 10 tahta; koyu kareler ince çizgilerle taranmış."],["Katlama izi","Kâğıtta kalan kat izi; belki katlanıp taşınıyordu."]]},"dkaart":{"title":"Kesilip Kullanılacak Domino ve İskambil","artist":"Anonim (Brepols)","date":"1800–1833","place":"Belçika (Turnhout)","game":"Domino ve iskambil","medium":"Mavi, kırmızı ve sarıyla boyanmış ağaç baskı; matbaa harfli metin","size":"34,3 × 41,9 cm","credit":"","p":["Müze kaydına göre bu kâğıtta kesilip kullanılacak 32 iskambil kâğıdı ve 28 domino taşı basılı. Yayıncı Brepols’un listesinde 114 numaradır; altta satıcı “D. Pouwels, Bergen-op-Zoom” yazar. Başlık Felemenkçe ve Fransızcadır.","Solda boş-boştan altı-altıya 28 taş üçgen biçiminde dizilmiş. Sağda her renkten yediden ona ve resimli kâğıtlarla asların oluşturduğu 32 kâğıt var: piket gibi oyunlar için bir deste. Kimse kesmediği için baskıdan çıktığı hâliyle görüyoruz."],"spots":[["Başlık","“DOMINO EN KAARTSPEL” yazısı."],["Boş-boş","Üçgenin tepesi: hiç noktası olmayan taş."],["Altı-altı","En büyük taş, en alt sıranın sağ ucunda."],["Maça ası","Sol sütunda yukarıdan ikinci kâğıt."],["Resimli kâğıt","Kırmızı, mavi ve sarıyla boyanmış bir papaz."],["Satıcı","Alttaki “D. POUWELS, Bergen-op-Zoom”."]]},"apen":{"title":"Tavla Oynayan İki Maymun","artist":"Quirin Boel, David Teniers’in tasarımından","date":"1635–1690","place":"Flandre","game":"Triktrak (tavlanın bir türü)","medium":"Asitle oyma baskı","size":"11,0 × 14,5 cm","credit":"","p":["Maymunların insan uğraşlarını canlandırdığı, bir başlık ve altı levhadan oluşan dizinin bir parçası. Sol altta “D. Teniers tasarladı ve yayımladı, imtiyazla” yazar; Quirin Boel, Flaman ressam Teniers’in tasarımını baskıya aktarmıştır.","Müze kaydının anlattığı gibi iki maymun yere oturmuş, aralarında bir triktrak tahtası var. Soldaki kadehten şarap içiyor, sağdaki horoz tüylü şapkasıyla bir pula uzanıyor. Büyük olasılıkla içkiye ve kumara dalmış insanlarla alay ediyor."],"spots":[["Tahta","Yerdeki katlanır triktrak tahtası; hanelerle pullar görülüyor."],["Soldaki maymun","Ceketli, tahtanın önünde oturan maymun."],["Şarap kadehi","Soldaki maymunun kaldırdığı kadeh."],["Tüylü şapka","Sağdaki maymunun şapkasındaki horoz tüyü."],["Testi","Soldaki maymunun ayağının dibindeki testi."],["Yazı","“D Teniers in et excud cum privilegio”."]]},"dstereo":{"title":"Masada Domino Oynayan Adamlar (Stereo Fotoğraf)","artist":"Anonim","date":"1850–1880","place":"Bilinmiyor (Felemenkçe yazı)","game":"Domino","medium":"Albümin baskı (stereo fotoğraf)","size":"8,5 × 17,0 cm","credit":"","p":["Bir stereo fotoğraf: yan yana neredeyse aynı iki fotoğraf. Stereoskopla bakılınca derinlikli tek bir sahneye dönüşür. Sol kenarda el yazısıyla “Het dominospel” (domino oyunu) yazar.","Bir binanın önünde güneşe bir masa konmuş; gömlekli adamlar taşlarını tutuyor. İkisi ayakta oyunu izliyor; sağdaki beyaz takke giymiş. Herkesin kıpırdamaması gerektiğinden sahne büyük olasılıkla fotoğraf için kurulmuştur."],"spots":[["Masadaki taşlar","Elde kapalı tutulan domino taşları."],["Beyaz takkeli adam","Sağda oturan, taşlarını tutan adam."],["Boyun atkılı adam","Ayakta, oyuna yukarıdan bakan adam."],["Soldaki adam","Dirseğine dayanıp taşlarına bakan genç."],["Yazı","Sol kenardaki “Het dominospel.”."],["İkinci görüntü","Biraz kaydırılmış noktadan çekilen sağdaki fotoğraf; ikisi birlikte derinlik verir."]]},"gojo":{"title":"Go Oynayan İki Kadın","artist":"Anonim","date":"1870–1891","place":"Japonya","game":"Büyük olasılıkla go","medium":"Elle boyanmış albümin baskı","size":"9,0 × 13,5 cm","credit":"","p":["Siyah beyaz bir fotoğrafın fırçayla elle boyanmış hâli. Bu tür fotoğraflar Yokohama gibi yerlerdeki stüdyolarda yabancılara hatıra olarak yapılırdı. Bu fotoğraf Manila’ya bir yolculuğun albümüne yapıştırılmıştı.","Bir niş süslemesi ve paravanın önünde iki kadın ayaklı bir tahtanın iki yanında oturuyor; soldaki bir taş koyuyor. Tahtada beyaz ve siyah taşlar var; büyük olasılıkla go, ama müze kaydında “bir masa oyunu” denir. Öndeki tepside tatlılar ve kaplar duruyor."],"spots":[["Tahta ve taşlar","Ayaklı kalın bir tahta, beyaz ve siyah taşlar."],["Taş koyan el","Soldaki kadın bir taş koyuyor."],["Soldaki kadın","Bize dönmüş; kuşağı büyük bir fiyonkla bağlı."],["Sağdaki kadın","Çizgili kimonolu, eli tahtanın yanında."],["Tepsi ve kaplar","Öndeki tatlılar ve fincanlar."],["Çiçekler","Arkada ayaklı bir sehpada çiçek vazosu."]]},"meade":{"title":"Satranç Oynayan İki Adam","artist":"Charles Richard Meade ve Henry William Mathew Meade","date":"1852","place":"Amerika Birleşik Devletleri","game":"Satranç","medium":"Dagerotip","size":"6,9 × 8,3 cm","credit":"","p":["İngiltere doğumlu, Amerika’da çalışan Meade kardeşlerin stüdyosundan bir dagerotip. Dagerotip görüntüyü doğrudan gümüş kaplı bir bakır levhada oluşturur; bu yüzden her biri tektir ve çoğaltılamaz. Bu, yaldızlı bir paspartunun ardında küçük bir deri kutuda durur.","İki genç adam küçük bir sehpadaki satranç tahtasının iki yanında; soldaki parmaklarını bir taşa koymuş. Sağdaki elini göğsüne koymuş, tahtayı inceliyor. Uzun süre kıpırdamamaları gerektiğinden hamle büyük olasılıkla poz içindir."],"spots":[["Satranç tahtası","Çiçekli kumaş örtülü sehpada tahta ve beyaz taşlar."],["Soldaki adam","Parmakları bir taşta."],["Sağdaki adam","Tahtaya bakıyor."],["Göğüsteki el","Sağdaki oyuncunun düşünceli eli."],["Örtü","Çiçekli kumaşla örtülü küçük sehpa."],["Yaldızlı paspartu","Levhayı koruyan yaldızlı çerçeve ve kutu."]]}};
